    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String[] paths = new String[n], contents = new String[n];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            paths[i] = st.nextToken();
            contents[i] = st.nextToken();
        }
        List<List<String>> groups = findDuplicates(paths, contents);
        StringBuilder sb = new StringBuilder();
        sb.append(groups.size()).append("\n");
        for (List<String> g : groups) sb.append(String.join(" ", g)).append("\n");
        System.out.print(sb);
    }
